// Generated by `just generate` from `src/plugins/claudetto/slices/ground/domain/claims.ts`. Edit the source and run `just generate`.
// The source check of `ground`: the claims of a new text that no source of the session backs.
// A source is a user message, a tool result, or a file of the project.
// The six kinds are numbers, `file:line` references, attributions to the user, conventions, and done-claims.
// A line with `(proposed)` or `[NEEDS CLARIFICATION: ...]`, and a fenced code block, pass.
// Only checks that a program can run, with no model call, because a check that guesses blocks correct text.
// The functions are pure: `adapters/` reads the session and the files.

import { lineCount } from "../../../kernel/text.ts";

/** One message of the session, as the check reads it. `results` are the tool results of the message. */
export interface Msg {
  role: "user" | "assistant";
  text: string;
  results: readonly string[];
  bash: number;
}

/** The content of each file that `neededFiles` names, or `null` when the file is absent. */
export type Files = Readonly<Record<string, string | null>>;

const REF =
  /(?<![\w/.-])((?:[\w.-]+\/)*[\w.-]+\.(?:tsx?|jsx?|mjs|py|md|json|rs|go|sh|toml|ya?ml|java|c|h|cpp)):(\d+)(?:-(\d+))?/g;
const NUMBER = /(?<![\w.,:/#$-])(\d{1,3}(?:,\d{3})+|\d{3,})(?![\w:/-]|[.,]\d)/g;
/** A number that is part of the name of a standard, such as `ISO 8601` or `RFC 3339`. It names a document and is no claim. */
const STANDARD =
  /\b(?:ISO|IEC|RFC|BCP|STD|PEP|IEEE|ANSI|ECMA|DIN)[ -]?\d[\d.:-]*/g;
/** A size in a binary unit, such as `16 MiB`. */
const SIZE = /(\d+(?:\.\d+)?)\s*(KiB|MiB|GiB|TiB)\b/g;
const SOURCE_NUMBERS_MAX = 400;
const CELL = /^\s*\+?(\d{1,3}(?:,\d{3})+|\d+)\b/;
const USER =
  /\bthe user (?:chose|said|decided|wants|asked|prefers|approved|confirmed|requested|told|picked|stated)\b([^.\n]*)/gi;
const DONE =
  /\b(?:(?:all\s+)?(?:tests?|checks?|lint|build|typecheck)\s+(?:now\s+)?(?:pass(?:es|ed)?|succeed(?:s|ed)?)|(?:is|are|was|now|been)\s+fixed)\b/i;
const FUTURE =
  /\b(?:must|should|will|would|can|could|if|when|until|before|after|unless|need|needs|then|expect)\b|^\W*(?:check|verify|done when|accept)/i;
const MARK = /\(proposed\)|\[NEEDS CLARIFICATION/i;
/** The tools that the lock files of a project forbid, and the lock files. */
const CONVENTIONS: readonly [readonly string[], string[]][] = [
  [
    ["bun.lock", "bun.lockb"],
    ["npm", "npx"],
  ],
  [["uv.lock"], ["pip", "pip3"]],
];
/** The words that make a tool name in prose a command: a subcommand, a flag, or a package for `npx`. */
const SUBCOMMANDS: Readonly<Record<string, string>> = {
  npm: "i|install|ci|run|test|start|build|exec|init|publish|update|uninstall|add|remove|link|pack|audit|ls|rebuild|version|-\\w+",
  npx: "[\\w@-]+",
  pip: "install|uninstall|freeze|list|show|download|wheel|-\\w+",
  pip3: "install|uninstall|freeze|list|show|download|wheel|-\\w+",
};
const command = (tool: string) =>
  new RegExp(
    `(?<![\\w/.-])${tool}\\s+(?:${SUBCOMMANDS[tool] ?? "[\\w@-]"})(?![\\w-])`,
  );

/** The files of the project that `findUnsourced` reads from the root: the rules and the lock files. */
export const PROJECT_FILES: readonly string[] = [
  "CLAUDE.md",
  ...CONVENTIONS.flatMap(([locks]) => locks),
];

/** The files that `text` references with `file:line`. A reference is not always relative to the root. */
export const refFiles = (text: string): string[] => [
  ...new Set([...text.matchAll(REF)].map((m) => m[1] as string)),
];

const NEGATION = /\b(?:not|never|no)\b/i;

/** The lines of `text` that the check reads. */
const proseLines = (text: string): string[] =>
  text
    .replace(/```[\s\S]*?```/g, "")
    .split("\n")
    .filter((line) => !MARK.test(line));

/** The totals of a table: a number of a row that is the sum of the numbers above it in the same column, for two rows or more. */
const columnTotals = (lines: readonly string[]): Set<number> => {
  const totals = new Set<number>();
  let rows: (number | null)[][] = [];
  for (const line of lines) {
    if (!line.trimStart().startsWith("|")) {
      rows = [];
      continue;
    }
    const cells = line
      .trim()
      .slice(1)
      .split("|")
      .map((c) => {
        const m = CELL.exec(c);
        return m ? Number((m[1] as string).replace(/,/g, "")) : null;
      });
    cells.forEach((v, i) => {
      if (v === null) return;
      const above = rows.map((r) => r[i] ?? null).filter((x) => x !== null);
      if (above.length >= 2 && above.reduce((a, b) => a + b, 0) === v)
        totals.add(v);
    });
    rows.push(cells);
  }
  return totals;
};

/** The claims of `text` with no source in `msgs`, in `files`, or in `own`, the old text of the target file.
 * A file of a reference that is `null` did not resolve, and the check skips it, because a guess would deny a correct reference. */
export const findUnsourced = (
  text: string,
  msgs: readonly Msg[],
  files: Files,
  own = "",
): string[] => {
  const user = msgs
    .filter((m) => m.role === "user")
    .map((m) => m.text)
    .join("\n");
  const rules = files["CLAUDE.md"] ?? "";
  const corpus = [user, ...msgs.flatMap((m) => m.results), rules, own]
    .join("\n")
    .replace(/(?<=\d)[,_](?=\d{3})/g, "");
  const turn = msgs.slice(
    msgs.findLastIndex((m) => m.role === "user" && m.text !== "") + 1,
  );
  const claims = new Set<string>();
  const prose = proseLines(text);
  const has = (n: string) => new RegExp(`(?<!\\d)${n}(?!\\d)`).test(corpus);
  const numbersOf = (line: string) =>
    [...line.replace(STANDARD, "").matchAll(NUMBER)].map((m) =>
      (m[1] as string).replace(/,/g, ""),
    );
  // A number that the text computes from numbers with a source: a column total, a sum, a difference, or a binary size.
  const totals = columnTotals(prose);
  const operands = [...new Set(prose.flatMap(numbersOf))]
    .map(Number)
    .filter((n) => totals.has(n) || has(String(n)))
    .slice(0, SOURCE_NUMBERS_MAX);
  const derived = (n: number, line: string) =>
    [...line.matchAll(SIZE)].some(
      ([, k = "", unit = ""]) =>
        Number(k) * 1024 ** ("KMGT".indexOf(unit[0] as string) + 1) === n,
    ) || operands.some((a) => operands.some((b) => a - b === n || a + b === n));
  for (const line of prose) {
    for (const [, num = ""] of line.replace(STANDARD, "").matchAll(NUMBER)) {
      const n = num.replace(/,/g, "");
      if (/^(?:19|20)\d\d$/.test(n)) continue;
      if (!has(n) && !totals.has(Number(n)) && !derived(Number(n), line))
        claims.add(`\`${num}\` is in no user message and no tool result.`);
    }
    for (const [ref = "", file = "", from = "", to = from] of line.matchAll(
      REF,
    )) {
      const body = files[file];
      if (body != null && Number(to) > lineCount(body))
        claims.add(`\`${ref}\`: the file has ${lineCount(body)} lines.`);
    }
    for (const [, said = ""] of line.matchAll(USER)) {
      const words = (said.toLowerCase().match(/[a-z]{5,}/g) ?? []) as string[];
      const known = words.filter((w) => user.toLowerCase().includes(w));
      if (words.length > 0 && known.length * 2 < words.length)
        claims.add(`"the user${said.trimEnd()}" is in no user message.`);
    }
    if (
      DONE.test(line) &&
      !FUTURE.test(line) &&
      turn.every((m) => m.bash === 0)
    )
      claims.add(
        `"${line.trim().slice(0, 80)}" has no check output in this turn.`,
      );
  }
  // A rule names the tool in a line with no negation. In a project file, the tool is also in backticks.
  const isRule = (l: string, tool: string, strict: boolean) =>
    !NEGATION.test(l) &&
    (strict ? new RegExp(`\`[^\`]*\\b${tool}\\b`) : command(tool)).test(l);
  for (const [locks, tools] of CONVENTIONS) {
    if (!locks.some((lock) => files[lock] != null)) continue;
    for (const tool of tools) {
      const rule = command(tool);
      const said = (t: string, strict: boolean) =>
        t.split("\n").some((l) => isRule(l, tool, strict));
      const used = prose.some(
        (l) => rule.test(l) && !NEGATION.test(l.slice(0, l.search(rule))),
      );
      if (used && !said(user, false) && !said(rules, true))
        claims.add(
          `\`${tool}\` in a project with \`${locks[0]}\`, and no user rule names it.`,
        );
    }
  }
  return [...claims];
};
